import java.nio.charset.StandardCharsets;
import org.jsoup.Connection.KeyVal;

public class UrlBuilderTest {

    @Test
    public void createUrlBuilderWithValidUrl() {
        URL url = new URL("https://example.com/path?a=1&b=2#fragment");
        UrlBuilder builder = new UrlBuilder(url);
        assertNotNull(builder.u);
    }

    @Test
    public void createUrlBuilderWithNullQuery() {
        URL url = new URL("https://example.com/path?query=value#fragment");
        UrlBuilder builder = new UrlBuilder(url);
        assertNull(builder.q);
    }

    @Test
    public void buildUrlWithoutQueryAndFragment() throws Exception {
        String expectedUrl = "https://example.com/path";
        UrlBuilder builder = new UrlBuilder(new URL(expectedUrl));
        assertEquals(expectedUrl, builder.u.toString());
    }

    @Test
    public void buildUrlWithQuery() throws Exception {
        String expectedUrl = "https://example.com/path?a=1&b=2";
        UrlBuilder builder = new UrlBuilder(new URL("https://example.com/path?query=value#fragment"));
        assertEquals(expectedUrl, builder.u.toString());
    }

    @Test
    public void buildUrlWithFragment() throws Exception {
        String expectedUrl = "https://example.com/path?a=1&b=2#fragment";
        UrlBuilder builder = new UrlBuilder(new URL("https://example.com/path?query=value"));
        assertEquals(expectedUrl, builder.u.toString());
    }

    @Test
    public void buildUrlWithInvalidProtocol() throws Exception {
        String expectedError = "Invalid protocol: https";
        try {
            UrlBuilder builder = new UrlBuilder(new URL("invalid.protocol://example.com/path"));
            fail(expectedError);
        } catch (MalformedURLException e) {
            assertEquals(expectedError, e.getMessage());
        }
    }

    @Test
    public void appendKeyVal() throws Exception {
        String expectedQuery = "key=1&value=2";
        UrlBuilder builder = new UrlBuilder(new URL("https://example.com/path"));
        Connection.KeyVal[] kvArray = {{Connection.KeyVal.KEY, "key"}, {Connection.KeyVal.VALUE, "value"}};
        for (Connection.KeyVal kv : kvArray) {
            builder.appendKeyVal(kv);
        }
        assertEquals(expectedQuery, String.format("%s?%s", builder.u.getProtocol(), builder.q.toString()));
    }

    @Test
    public void appendToAsciiWithNonASCIICharacter() throws Exception {
        StringBuilder expectedStringBuilder = new StringBuilder().append("+");
        UrlBuilder builder = new UrlBuilder(new URL("https://example.com/path"));
        String s = "ä";
        UrlBuilder.appendToAscii(s, false, builder.q);
        assertEquals(expectedStringBuilder.toString(), String.format("%s%s", String.format("%c", (char) 196), builder.q.toString()));
    }

    @Test
    public void appendToAsciiWithWhitespace() throws Exception {
        StringBuilder expectedStringBuilder = new StringBuilder().append("+");
        UrlBuilder builder = new UrlBuilder(new URL("https://example.com/path"));
        String s = " ";
        UrlBuilder.appendToAscii(s, true, builder.q);
        assertEquals(expectedStringBuilder.toString(), String.format("%s%s", String.format("%c", (char) 32), builder.q.toString()));
    }

    @Test
    public void appendToAsciiWithInvalidCharacter() throws Exception {
        StringBuilder expectedStringBuilder = new StringBuilder().append("+");
        UrlBuilder builder = new UrlBuilder(new URL("https://example.com/path"));
        String s = "\u0001";
        UrlBuilder.appendToAscii(s, false, builder.q);
        assertEquals(expectedStringBuilder.toString(), String.format("%s%s", String.format("%c", (char) 1), builder.q.toString()));
    }

}

